"""Veridex updater. Put this file in the veridex folder (next to README.md) and run:  python update_6.py"""
import base64, os
HERE = os.path.dirname(os.path.abspath(__file__))
FILES = {'core/checker.py': '', 'core/idents.py': '', 'zeus/honeypot.py': '', 'db.py': '', 'bot/telegram_bot.py': '', 'tools/make_demo_audio.py': '', 'data/sec_unlicensed_entities_warnings.csv': '', 'data/sec_licensed_2026q1.csv': '', 'data/sec_enforcement_q1_2026.csv': '', 'data/benchmark_rates.csv': '', 'data/known_bad_domains.csv': ''}
for rel, b in FILES.items():
    p = os.path.join(HERE, *rel.split("/"))
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, "wb").write(base64.b64decode(b))
    print("updated", rel)
print("Done. Now run: pip install -r requirements.txt   then restart the bot.")
